<?php $e=static fn(mixed $value):string=>App\Core\View::e($value); $csrf=App\Core\Security::csrfToken(); ?>
<section class="simulation-workspace">
<div class="section-heading"><div><p class="eyebrow">SIMULAÇÃO INTERNA</p><h1><?= $e($scenario['name']) ?></h1><p><?= $e($scenario['championship_name']) ?> · <?= $e($scenario['phase_name']) ?>. Dados oficiais permanecem intactos.</p></div><div class="actions"><?php if($canEdit): ?><form method="post" action="<?= $e(App\Core\Config::url('/admin/simulacoes/'.$scenario['id'].'/duplicar')) ?>"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><button class="secondary">Duplicar</button></form><?php endif; ?></div></div>
