<?php if($canEdit): ?><div class="simulation-actions"><form method="post" action="<?= $e(App\Core\Config::url('/admin/simulacoes/'.$scenario['id'].'/referencias')) ?>"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><label>Partida oficial como referência<select name="reference_match_id"><?php foreach($referenceMatches as $match): ?><option value="<?= (int)$match['id'] ?>"><?= $e($match['home_team_name']) ?> × <?= $e($match['away_team_name']) ?></option><?php endforeach; ?></select></label><button>Adicionar</button></form><form method="post" action="<?= $e(App\Core\Config::url('/admin/simulacoes/'.$scenario['id'].'/rodada')) ?>"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><label>Simular rodada completa<select name="round_id"><?php foreach($rounds as $round): ?><option value="<?= (int)$round['id'] ?>"><?= $e($round['group_name']) ?> · Rodada <?= (int)$round['round_number'] ?></option><?php endforeach; ?></select></label><button class="secondary">Aplicar 0 × 0</button></form><form method="post" action="<?= $e(App\Core\Config::url('/admin/simulacoes/'.$scenario['id'].'/hipoteticas')) ?>"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><label>Grupo<select name="group_id"><?php foreach($groups as $group): ?><option value="<?= (int)$group['id'] ?>"><?= $e($group['name']) ?></option><?php endforeach; ?></select></label><label>Mandante<select name="home_team_id"><?php foreach($teams as $groupTeams): foreach($groupTeams as $team): ?><option value="<?= (int)$team['team_id'] ?>"><?= $e($team['team_name']) ?></option><?php endforeach; endforeach; ?></select></label><label>Visitante<select name="away_team_id"><?php foreach($teams as $groupTeams): foreach($groupTeams as $team): ?><option value="<?= (int)$team['team_id'] ?>"><?= $e($team['team_name']) ?></option><?php endforeach; endforeach; ?></select></label><button class="secondary">Criar confronto hipotético</button></form></div><?php endif; ?>
<div class="table-wrap"><table><thead><tr><th>Confronto simulado</th><th>Placar</th><th>W.O.</th><th>Eventos</th></tr></thead><tbody><?php foreach($matches as $match): ?><tr><td><?= $e($match['home_team_name']) ?> × <?= $e($match['away_team_name']) ?></td><td><?php if($canEdit): ?><form class="inline-form" method="post" action="<?= $e(App\Core\Config::url('/admin/simulacoes/'.$scenario['id'].'/partidas/'.$match['id'].'/placar')) ?>"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><input name="home_score" type="number" min="0" max="99" value="<?= $match['home_score']!==null?(int)$match['home_score']:'' ?>"><b>×</b><input name="away_score" type="number" min="0" max="99" value="<?= $match['away_score']!==null?(int)$match['away_score']:'' ?>"><select name="wo_winner_team_id"><option value="">Sem W.O.</option><option value="<?= (int)$match['home_team_id'] ?>">W.O. <?= $e($match['home_team_name']) ?></option><option value="<?= (int)$match['away_team_id'] ?>">W.O. <?= $e($match['away_team_name']) ?></option></select><button>Salvar</button></form><?php else: ?><?= $match['home_score']??'-' ?> × <?= $match['away_score']??'-' ?><?php endif; ?></td><td><?= $match['wo_winner_team_id']?(int)$match['wo_winner_team_id']=== (int)$match['home_team_id']?$e($match['home_team_name']):$e($match['away_team_name']):'—' ?></td><td><?php foreach($events((int)$match['id']) as $event): ?><small><?= $e($event['event_type']) ?></small><?php endforeach; ?><?php if($canEdit): ?><form class="inline-form" method="post" action="<?= $e(App\Core\Config::url('/admin/simulacoes/'.$scenario['id'].'/partidas/'.$match['id'].'/eventos')) ?>"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><select name="team_id"><option value="<?= (int)$match['home_team_id'] ?>"><?= $e($match['home_team_name']) ?></option><option value="<?= (int)$match['away_team_id'] ?>"><?= $e($match['away_team_name']) ?></option></select><select name="event_type"><option value="goal">Gol</option><option value="yellow_card">Cartão amarelo</option><option value="red_card">Cartão vermelho</option><option value="penalty_scored">Pênalti</option></select><button class="secondary">Adicionar</button></form><form method="post" action="<?= $e(App\Core\Config::url('/admin/simulacoes/'.$scenario['id'].'/partidas/'.$match['id'].'/restaurar')) ?>"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><button class="secondary">Restaurar</button></form><?php endif; ?></td></tr><?php endforeach; ?><?php if(!$matches): ?><tr><td colspan="4">Adicione uma partida oficial como referência ou simule uma rodada completa.</td></tr><?php endif; ?></tbody></table></div>
<?php if($canCompare): ?><form class="filter-bar" method="get"><label>Comparar com cenário<select name="comparar"><option value="">Classificação oficial</option><?php foreach($availableScenarios as $candidate): if((int)$candidate['id']!==(int)$scenario['id']&&(int)$candidate['championship_id']===(int)$scenario['championship_id']&&(int)$candidate['phase_id']===(int)$scenario['phase_id']): ?><option value="<?= (int)$candidate['id'] ?>" <?= $comparisonScenario&&(int)$comparisonScenario['id']===(int)$candidate['id']?'selected':'' ?>><?= $e($candidate['name']) ?></option><?php endif; endforeach; ?></select></label><button>Comparar</button></form><?php endif; ?><h2>Comparação da classificação<?= $comparisonScenario?' com '.$e($comparisonScenario['name']):' oficial' ?></h2><div class="simulation-standings"><?php foreach($projection as $groupId=>$tables): ?><article><h3>Grupo <?= $e($groups[array_search($groupId,array_column($groups,'id'))]['name']??'') ?></h3><div class="table-wrap"><table><thead><tr><th>#</th><th>Equipe</th><th>Pontos</th><th>Variação</th><th>Situação</th></tr></thead><tbody><?php foreach($tables['simulated'] as $row): ?><tr><td><?= (int)$row['position'] ?></td><td><?= $e($row['team_name']) ?></td><td><?= (int)$row['points'] ?> <?php if($row['points_difference']): ?><small>(<?= $row['points_difference']>0?'+':'' ?><?= (int)$row['points_difference'] ?>)</small><?php endif; ?></td><td><?= $row['position_change']>0?'Subiu '.$row['position_change']:($row['position_change']<0?'Caiu '.abs($row['position_change']):'Sem alteração') ?></td><td><?= $row['situation']==='qualified'?'Classificado':'Eliminado' ?></td></tr><?php endforeach; ?></tbody></table></div></article><?php endforeach; ?></div>
<?php if($crossings): ?><h2>Possíveis cruzamentos</h2><div class="simulation-crossings"><?php foreach($crossings as $crossing): ?><article><p><?= $e($crossing['label']) ?></p><strong><?= $e($crossing['home_team']['team_name']??$crossing['home_source']) ?></strong><span>×</span><strong><?= $e($crossing['away_team']['team_name']??$crossing['away_source']) ?></strong></article><?php endforeach; ?></div><?php endif; ?>
<?php if($canManage): ?><div class="actions"><form method="post" action="<?= $e(App\Core\Config::url('/admin/simulacoes/'.$scenario['id'].'/arquivar')) ?>"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><button class="secondary">Arquivar cenário</button></form><form method="post" action="<?= $e(App\Core\Config::url('/admin/simulacoes/'.$scenario['id'].'/excluir')) ?>"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><button class="danger">Excluir cenário</button></form></div><?php endif; ?>
